  // 병종 분류: infantry=T1 병영 / heavy=T2 중화기 지원소 / support=T3 차량 정비소 / 그 외=T4 전차 공창
  const CATS = {};
  ['infantry', 'engineer', 'at_inf', 'sniper', 'commando', 'ranger', 'jager', 'panzergren',
   'scout', 'pathfinder', 'paratrooper', 'assault_eng', 'captain', 'fp_pioneer', 'fj', 'sturmtruppen'].forEach(k => CATS[k] = 'infantry');
  ['hmg', 'hmg_50', 'mortar', 'at_gun', 'm5gun', 'pack75', 'lg40', 'flak', 'flak38', 'flak36'].forEach(k => CATS[k] = 'heavy');
  ['ambulance', 'transport', 'supply', 'vehicle', 'puma', 'bergepanzer', 'howitzer', 'obice210', 'priest', 'nebel', 'pzb221', 'stummel', 'amb251', 'hummel',
   'scott', 'wespe', 'whizbang', 'recovery', 'truck', 'weasel', 'kettenkrad', 'm16', 'm3gmc'].forEach(k => CATS[k] = 'support');
  ['blue', 'red'].forEach(tm => Object.keys(UNIT_ROSTER[tm]).forEach(k => { const t = UNIT_ROSTER[tm][k]; t.cat = CATS[k] || 'tank'; if (t.fcost === undefined) t.fcost = t.armorType === 'hard' ? Math.round(t.cost * 0.1 / 5) * 5 : 0; }));

